"""Publish separate firmware progress without changing the connected game proof."""
import json,hashlib,shutil
from pathlib import Path
from datetime import datetime,timezone
ROOT=Path(__file__).resolve().parents[1];RUNTIME=Path.home()/'.lmstudio/local-ai-lab'
save=lambda p,v:p.write_text(json.dumps(v,indent=2,ensure_ascii=False)+'\n')
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()

def main():
    proof=json.loads((ROOT/'verification/firmware-DSP-auth-live-checks.json').read_text())
    body=proof['standalone_proof'];assert body['emulator_shutdown_completed'] and proof['firmware_DSP_instruction_coverage']==[462,462]
    assert not proof['initial_DSP_boundary_hostloaded'] and not proof['source_success_word_injected'] and not proof['complete_firmware_boot_verified']
    out=ROOT/'verification/firmware-DSP-progress-review'/datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%S.%fZ');out.mkdir(parents=True)
    compact={k:proof[k]for k in ['status','recorded_at','initial_CPU_PC','relocated_entry_PC','CPU_first_DSP_wait_PC','firmware_DSP_instructions','firmware_DSP_instruction_coverage','firmware_DSP_checkpoints','firmware_DSP_success_word','CPU_continuation_steps','next_CPU_wait_PC','next_GPU_PC','native_CPU_firmware_instructions_used','CPU_firmware_C_beyond_bootstrap_verified','firmware_DSP_C','original_DSP_instructions_on_C_path','initial_DSP_boundary_hostloaded','decrypted_code_host_copy','source_success_word_injected','emulator_BIOS_boot_stub_injection_disabled','emulator_GPU_auth_magic_stomp_disabled','CPU_reseeded_after_initial_ROM_entry','DSP_equivalence_bytes','DSP_pipeline_tail_excluded_bytes','complete_firmware_boot_verified','disc_attached','boot_stub_source_loaded','linked_into_full_C_game_startup','whole_game_complete','implementation_authorship','local_model_authored_bodies_added','limits']}
    compact.update(scope='Separate hybrid originalCPU + reconstructedDSP firmware prefix. Existing connectedgame C chain still starts with supplied60000byte stub; the new firmware prefix is not linked to it.',plain_language_summary='The firmware now reaches and completes its first DSP check using reconstructed C. Its own arithmetic produces/decrypts the code it needs and checks the supplied retailROM, then the CPU continues naturally to a GPU wait. This removes a missing DSP dependency in the separate firmware prefix. Firmware CPU still runs original instructions; GPU drawing/shutdown, actual disc header/loading and firmware-to-game dispatch are unfinished.',full_report=str(ROOT/'verification/firmware-DSP-auth-live-checks.json'),audit=str(out))
    save(out/'compact-evidence.json',compact)
    compact['processor_responsibilities']={'original_CPU':'Loads the DSP code/data, starts it, waits for GO to clear, reads its success word, then continues. CPU does NOT perform the DSP decryption or ROM check. Firmware CPU beyond bootstrap still runs original instructions.','reconstructed_C_DSP':'Executes the decryption/arithmetic, produces its plaintext code, checks the supplied ROM, writes the success word and clears its own GO bit. The linked C DSP uses live CPU-loaded state.','GPU':'Still waiting to be executed/reconstructed for firmware drawing/shutdown; existing gameGPU C paths are a separate later game test.'}
    save(out/'compact-evidence.json',compact)
    session=Path(json.loads((ROOT/'projects/black-ice-white-noise/analysis/current-session.json').read_text())['directory'])
    installed=Path(json.loads((RUNTIME/'projects/black-ice-white-noise/analysis/current-session.json').read_text())['directory'])
    for folder in [session,installed]:
        path=folder/'emulator-runtime/summary.json';shutil.copy2(path,out/('prior-installed-summary.json'if folder==installed else'prior-workspace-summary.json'))
        data=json.loads(path.read_text());data['firmware_bootstrap_DSP_progress']=compact;save(path,data)
    for name in ['chat_tools.py','CURRENT DECOMPILATION.txt','CURRENT LOCAL INFERENCE.txt','START HERE.txt']:
        shutil.copy2(ROOT/name,out/('prior-'+name))
    shutil.copy2(RUNTIME/'chat_tools.py',out/'prior-installed-chat_tools.py')
    files=[ROOT/'verification/firmware-DSP-auth-live-checks.json',ROOT/'verification/firmware-DSP-auth-checks.json',ROOT/'verification/firmware-DSP-auth-native-discovery.json',ROOT/'verification/relocated-firmware-DSP-C-linked.json',ROOT/'scripts/observe_biwn_relocated_firmware.py',ROOT/'scripts/generate_biwn_firmware_DSP_auth.py',ROOT/'scripts/check_biwn_firmware_DSP_auth.py',ROOT/'scripts/check_biwn_firmware_DSP_live_link.py',Path(body['directory'])/'generator-at-verification.py',Path(body['directory'])/'test-at-verification.py',Path(body['directory'])/'protocol.json',Path(body['directory'])/'report.json',Path(body['directory'])/'status.json',Path(body['directory'])/'checkpoint-comparisons.json',Path(body['directory'])/'native-final-DSP.bin',Path(body['directory'])/'C-final-DSP.bin',ROOT/'projects/black-ice-white-noise/restoration/biwn_firmware_DSP_auth.c',ROOT/'projects/black-ice-white-noise/restoration/biwn_firmware_DSP_auth.h',session/'firmware-DSP-auth-generation.json']
    for directory in [Path(proof['native_directory']),Path(proof['C_directory'])]:
        files.extend(directory/n for n in ['protocol.json','report.json','status.json','DSP-at-CPU-wait.bin','DSP-after-first-program.bin','RAM-at-relocated-entry.bin','RAM-final.bin','RAM-after-first-DSP.bin','RAM-after-CPU-continuation.bin','CPU-continuation.json'])
    manifest=[]
    for i,source in enumerate(files):
        target=out/f'{i:02d}-{source.name}';shutil.copy2(source,target);manifest.append(dict(source=str(source),snapshot=str(target),sha256=sha(target)))
    review=dict(status='verified_live_firmware_DSP_progress_full_goal_incomplete',recorded_at=datetime.now(timezone.utc).isoformat(),directory=str(out),previous_goal_turn_classification='progress:49instructionrelocation and nativeChat proof changed authoritative state',this_goal_turn_classification='progress:462instructionguardedDSP reconstruct and natural live firmware link',evidence=compact,who_did_what=dict(coordinator='Traced originalCPU firmware with emulator injection/magic shortcuts disabled, reconstructed462DSP source blocks including decrypted code, tested516checkpoints and linked C DSP to naturalCPUloader state.',local_model='No code-generation prompt or accepted source body this step. Native Chat review attempted after source work; AX observation timed out. Prior two verified role responses remain in earlier native export.',independent_validation='Pinned originalDSP and reconstructedC compared with matching CPU/RAM/peripherals/logicalDSP/PCtraces/counts; originalCPU still used on both sides of firmware prefix.'),model_defaults_changed=False,new_weight_training=False,AD_analysis_pilot_v2='Previously trained/loadable/unpromoted; unchanged this source step',local_model_accepted_body_counts_unchanged=True,native_UI_this_step_status='AX request timed out; no new prompt sent',whole_goal_complete=False,manifest=manifest,next_source_work=['Execute/reconstruct source GPU drawing/shutdown atGPUF03A78 to release CPU5028A..50292 wait, preserving live state.','Reconstruct remaining firmwareCPU/DSP/controller/disc-header-load/dispatch; replace supplied60000byte game stub and hostTOCprelude in full C game test.','Replace controlled globalclocks/poses/input/taskquiescence and remaining tasks/scenes/music/modalpaths; full game remains incomplete.'])
    save(out/'review.json',review);save(ROOT/'verification/firmware-DSP-progress-review.json',review)
    (out/'who-prompts-and-responses.txt').write_text('Coordinator-authored source work. No local-model code prompt or new weight training.\nOriginalDSP/C verification is independent of a model reviewer.\n\nVerified source findings:\n'+json.dumps(compact,indent=2)+'\n\nNative UI observation: request timed out; no new prompt was sent. Previous visible prompts/responses:\n'+str(ROOT/'verification/firmware-relocation-review/20261015T011820.772829Z/native-chat-export.md')+'\n')
    current=ROOT/'CURRENT DECOMPILATION.txt';current.write_text('FIRMWARE DSP CHECK LINKED TO LIVE CPU BOOTSTRAP\n'+review['recorded_at']+'\n\n'+compact['plain_language_summary']+'\n\n462observedDSPinstructions/10,460,888executed instructions/516checkpoints match. Live originalCPU supplies DSP state; C path executes nooriginalDSP, injectsnosuccessmagic,hostloadsnodecryptedcode,reseedsnoCPUatcompletion. LogicalDSP8496/bothbanks,fullCPU/privateRAM/GPU/TOM/JERRY/DAC/CDROM/traces/counts match;233DSPpipeline bytes remain an excluded initialtail provider. Explicit blockedCPU/DSP alternation remains timing policy.\n\nAUDIT\n'+str(out)+'\n\nNEXT\n'+'\n'.join(review['next_source_work'])+'\n\nEARLIER CHECKPOINTS\n'+current.read_text())
    npath=ROOT/'verification/NEXT SOURCE AND INFERENCE WORK.json';n=json.loads(npath.read_text());n.update(source_audit=str(out),last_turn_classification='progress',last_turn_authorship=review['who_did_what'],firmware_DSP_live_C_verified=True,firmware_DSP_code_host_copy=False,native_UI_current_step_status=review['native_UI_this_step_status'])
    n['next_source_work'][0]=review['next_source_work'][0]+' '+review['next_source_work'][1];save(npath,n)
    assert all(sha(Path(item['snapshot']))==item['sha256']for item in manifest)
    print(out)

if __name__=='__main__':main()
